1	//! # 导航功能
2	//!
3	//! 实现 LSP 的跳转定义、查找引用和文档大纲功能：
4	//! - `goto_definition`：跳转到标签定义或 callScript 目标文件
5	//! - `find_references`：查找标签的所有引用
6	//! - `document_symbols`：文档大纲（章节 / 标签 / 分支）
7	
8	use tower_lsp::lsp_types::{
9	    DocumentSymbol, GotoDefinitionParams, GotoDefinitionResponse, Location, Position, Range,
10	    ReferenceParams, SymbolKind, Url,
11	};
12	use vn_runtime::script::ast::ScriptNode;
13	
14	use crate::state::{DocumentState, ServerState};
15	
16	/// 跳转定义。
17	///
18	/// - `goto <label>` 行 → 标签定义位置
19	/// - `callScript "path"` 行 → 目标脚本文件起点
20	pub(crate) fn goto_definition(
21	    state: &ServerState,
22	    params: &GotoDefinitionParams,
23	) -> Option<GotoDefinitionResponse> {
24	    let uri = &params.text_document_position_params.text_document.uri;
25	    let pos = params.text_document_position_params.position;
26	    let doc = state.documents.get(uri)?;
27	    let line_text = get_line_text(&doc.content, pos.line);
28	    let trimmed = line_text.trim();
29	
30	    // goto <label>
31	    if trimmed.to_lowercase().starts_with("goto ") {
32	        let target = trimmed.get("goto ".len()..)?.trim();
33	        return find_label_location(doc, uri, target);
34	    }
35	
36	    // callScript "path"
37	    if trimmed.to_lowercase().starts_with("callscript ") {
38	        let after = trimmed.get("callscript ".len()..)?;
39	        let path = extract_quoted_string(after)?;
40	        return resolve_script_file(state, uri, &path);
41	    }
42	
43	    None
44	}
45	
46	/// 查找引用。
47	///
48	/// 在标签定义行（`* label`）上触发，返回该标签被 `goto` 或选择表格引用的所有位置。
49	pub(crate) fn find_references(state: &ServerState, params: &ReferenceParams) -> Vec<Location> {
50	    let uri = &params.text_document_position.text_document.uri;
51	    let pos = params.text_document_position.position;
52	    let Some(doc) = state.documents.get(uri) else {
53	        return Vec::new();
54	    };
55	    let line_text = get_line_text(&doc.content, pos.line);
56	    let trimmed = line_text.trim();
57	
58	    // 在标签定义行 `* label` 上 → 查找所有引用
59	    if let Some(rest) = trimmed.strip_prefix("* ") {
60	        let label_name = rest.trim();
61	        if !label_name.is_empty() {
62	            return find_label_references(doc, uri, label_name);
63	        }
64	    }
65	
66	    Vec::new()
67	}
68	
69	/// 文档大纲：章节、标签、选择分支。
70	pub(crate) fn document_symbols(state: &ServerState, uri: &Url) -> Vec<DocumentSymbol> {
71	    let Some(doc) = state.documents.get(uri) else {
72	        return Vec::new();
73	    };
74	    let Some(script) = &doc.script else {
75	        return Vec::new();
76	    };
77	
78	    let mut symbols = Vec::new();
79	    for (idx, node) in script.nodes.iter().enumerate() {
80	        // source_map 是 1-based 行号；转换为 0-based LSP 行号
81	        let line = script.get_source_line(idx).unwrap_or(1).saturating_sub(1) as u32;
82	        let range = Range::new(Position::new(line, 0), Position::new(line, 80));
83	
84	        match node {
85	            ScriptNode::Chapter { title, .. } => {
86	                symbols.push(make_symbol(
87	                    title.clone(),
88	                    SymbolKind::NAMESPACE,
89	                    range,
90	                    None,
91	                ));
92	            }
93	            ScriptNode::Label { name } => {
94	                symbols.push(make_symbol(
95	                    name.clone(),
96	                    SymbolKind::KEY,
97	                    range,
98	                    Some("label".to_string()),
99	                ));
100	            }
101	            ScriptNode::Choice { options, .. } => {
102	                let text: Vec<&str> = options.iter().map(|o| o.text.as_str()).collect();
103	                let name = format!("choice: {}", text.join(" / "));
104	                symbols.push(make_symbol(name, SymbolKind::ENUM, range, None));
105	            }
106	            _ => {}
107	        }
108	    }
109	    symbols
110	}
111	
112	// --- 内部辅助函数 ---
113	
114	/// 在文档中定位标签的源码位置。
115	fn find_label_location(
116	    doc: &DocumentState,
117	    uri: &Url,
118	    target: &str,
119	) -> Option<GotoDefinitionResponse> {
120	    let script = doc.script.as_ref()?;
121	    let idx = script.find_label(target)?;
122	    // source_map 是 1-based；转 0-based
123	    let line = script.get_source_line(idx)?.saturating_sub(1) as u32;
124	    Some(GotoDefinitionResponse::Scalar(Location {
125	        uri: uri.clone(),
126	        range: Range::new(Position::new(line, 0), Position::new(line, 0)),
127	    }))
128	}
