130	/// 将 callScript 路径解析为目标文件 URI。
131	fn resolve_script_file(
132	    _state: &ServerState,
133	    current_uri: &Url,
134	    path: &str,
135	) -> Option<GotoDefinitionResponse> {
136	    // 脚本路径相对于当前文件目录
137	    let current_path = current_uri.to_file_path().ok()?;
138	    let dir = current_path.parent()?;
139	    let target_path = dir.join(path);
140	    let target_uri = Url::from_file_path(target_path).ok()?;
141	    Some(GotoDefinitionResponse::Scalar(Location {
142	        uri: target_uri,
143	        range: Range::new(Position::new(0, 0), Position::new(0, 0)),
144	    }))
145	}
146	
147	/// 在文档中查找所有引用指定标签的行。
148	fn find_label_references(doc: &DocumentState, uri: &Url, label_name: &str) -> Vec<Location> {
149	    let mut refs = Vec::new();
150	    for (line_idx, line) in doc.content.lines().enumerate() {
151	        let trimmed = line.trim();
152	
153	        // `goto label`
154	        if trimmed.to_lowercase().starts_with("goto ")
155	            && let Some(target) = trimmed.get("goto ".len()..)
156	            && target.trim() == label_name
157	        {
158	            refs.push(make_location(uri, line_idx as u32));
159	        }
160	
161	        // 选择表格行中的标签引用（含有 `|` 且含有标签名）
162	        if trimmed.starts_with('|') && trimmed.contains(label_name) {
163	            refs.push(make_location(uri, line_idx as u32));
164	        }
165	    }
166	    refs
167	}
168	
169	/// 构造指向指定行的 Location。
170	fn make_location(uri: &Url, line: u32) -> Location {
171	    Location {
172	        uri: uri.clone(),
173	        range: Range::new(Position::new(line, 0), Position::new(line, 80)),
174	    }
175	}
