177	/// 构造 `DocumentSymbol`。
178	fn make_symbol(
179	    name: String,
180	    kind: SymbolKind,
181	    range: Range,
182	    detail: Option<String>,
183	) -> DocumentSymbol {
184	    #[expect(
185	        deprecated,
186	        reason = "DocumentSymbol.deprecated 字段已弃用但结构体字面量必须填写"
187	    )]
