1	//! # 诊断分析
2	//!
3	//! 将 vn-runtime 的解析和诊断结果转换为 LSP `Diagnostic` 格式，
4	//! 并存储到 `DocumentState` 中。
5	
6	use tower_lsp::lsp_types::{Diagnostic, DiagnosticSeverity, Position, Range, Url};
7	use vn_runtime::{
8	    diagnostic::{DiagnosticLevel, analyze_script, extract_resource_references},
9	    error::ParseError,
10	    script::{ast::Script, parser::Parser},
11	};
12	
13	use crate::{assets::AssetIndex, state::DocumentState};
14	
15	/// 分析文档内容，将解析和语义诊断写入 `DocumentState`。
16	///
17	/// `base_path` 为脚本文件所在目录相对于 `assets/` 的路径（如 `scripts/remake`），
18	/// 用于正确解析资源相对路径。
19	pub(crate) fn analyze_document(uri: &Url, doc: &mut DocumentState, base_path: &str) {
20	    let script_id = uri.as_str();
21	    let mut parser = Parser::new();
22	
23	    match parser.parse_with_base_path(script_id, &doc.content, base_path) {
24	        Ok(script) => {
25	            // 解析成功：进行语义分析
26	            let result = analyze_script(&script);
27	            doc.script = Some(script);
28	            doc.diagnostics = result.diagnostics.iter().map(vn_diag_to_lsp).collect();
29	        }
30	        Err(parse_err) => {
31	            // 解析失败：将 ParseError 转换为 LSP 诊断
32	            doc.script = None;
33	            doc.diagnostics = vec![parse_error_to_lsp(&parse_err)];
34	        }
35	    }
36	}
37	
38	/// 将 vn-runtime `Diagnostic` 转换为 LSP `Diagnostic`。
39	///
40	/// vn-runtime 行号从 1 开始，LSP 行号从 0 开始，转换时用 `saturating_sub(1)`。
41	fn vn_diag_to_lsp(diag: &vn_runtime::diagnostic::Diagnostic) -> Diagnostic {
42	    let line = diag.line.unwrap_or(1).saturating_sub(1) as u32;
43	    let range = single_line_range(line);
44	
45	    let severity = match diag.level {
46	        DiagnosticLevel::Error => DiagnosticSeverity::ERROR,
47	        DiagnosticLevel::Warn => DiagnosticSeverity::WARNING,
48	        DiagnosticLevel::Info => DiagnosticSeverity::INFORMATION,
49	    };
50	
51	    let message = if let Some(detail) = &diag.detail {
52	        format!("{}\n{}", diag.message, detail)
53	    } else {
54	        diag.message.clone()
55	    };
56	
57	    Diagnostic {
58	        range,
59	        severity: Some(severity),
60	        source: Some("ring-lsp".to_owned()),
61	        message,
62	        ..Default::default()
63	    }
64	}
65	
66	/// 将 `ParseError` 转换为 LSP `Diagnostic`。
67	///
68	/// vn-runtime 行号从 1 开始，LSP 行号从 0 开始，转换时用 `saturating_sub(1)`。
69	fn parse_error_to_lsp(err: &ParseError) -> Diagnostic {
70	    let (line_1based, message) = match err {
71	        ParseError::InvalidLine { line, message } => (*line, format!("无效的格式：{message}")),
72	        ParseError::UnknownCommand { line, command } => (*line, format!("未知指令：{command}")),
73	        ParseError::MissingParameter {
74	            line,
75	            command,
76	            param,
77	        } => (*line, format!("指令 '{command}' 缺少参数 '{param}'")),
78	        ParseError::InvalidParameter {
79	            line,
80	            param,
81	            message,
82	        } => (*line, format!("参数 '{param}' 无效：{message}")),
83	        ParseError::InvalidTable { line, message } => (*line, format!("无效的表格格式：{message}")),
84	        ParseError::InvalidTransition { line, message } => {
85	            (*line, format!("无效的过渡效果语法：{message}"))
86	        }
87	    };
88	
89	    let line = line_1based.saturating_sub(1) as u32;
90	    Diagnostic {
91	        range: single_line_range(line),
92	        severity: Some(DiagnosticSeverity::ERROR),
93	        source: Some("ring-lsp".to_owned()),
94	        message,
95	        ..Default::default()
96	    }
97	}
98	
99	/// 构造指向某行行首的零长度 Range（列 0..0）。
100	fn single_line_range(line: u32) -> Range {
101	    Range {
102	        start: Position { line, character: 0 },
103	        end: Position { line, character: 0 },
104	    }
105	}
106	
107	/// 验证文档中所有资源引用是否存在于 `AssetIndex` 中。
108	///
109	/// 使用 `ResourceReference::resolved_path`（由 parser 的 `base_path` 解析），
110	/// 规范化后查索引。
111	pub(crate) fn validate_resources(doc: &mut DocumentState, assets: &AssetIndex) {
112	    let Some(script) = &doc.script else {
113	        return;
114	    };
115	    let refs = extract_resource_references(script);
116	    for r in &refs {
117	        if r.path.is_empty() {
118	            continue;
119	        }
120	        let normalized = normalize_path(&r.resolved_path);
121	        if assets.exists(&normalized) {
122	            continue;
123	        }
124	        let line = find_resource_line(script, &r.path).unwrap_or(0);
125	        doc.diagnostics.push(Diagnostic {
126	            range: single_line_range(line),
127	            severity: Some(DiagnosticSeverity::WARNING),
128	            source: Some("ring-lsp".to_owned()),
129	            message: format!("资源不存在: {}", r.path),
130	            ..Default::default()
131	        });
132	    }
133	}
134	
135	/// 规范化路径：折叠 `..` 和 `.` 组件，统一使用 `/` 分隔符。
136	fn normalize_path(path: &str) -> String {
137	    let path = path.replace('\\', "/");
138	    let mut parts: Vec<&str> = Vec::new();
139	    for component in path.split('/') {
140	        match component {
141	            "" | "." => {}
142	            ".." => {
143	                parts.pop();
144	            }
145	            other => parts.push(other),
146	        }
147	    }
148	    parts.join("/")
149	}
150	
151	#[cfg(test)]
152	mod tests {
153	    use tower_lsp::lsp_types::Url;
154	
155	    use super::*;
156	    use crate::state::DocumentState;
157	
158	    fn make_doc(content: &str) -> DocumentState {
159	        DocumentState {
160	            content: content.to_string(),
161	            version: 1,
162	            script: None,
163	            diagnostics: Vec::new(),
164	        }
165	    }
166	
167	    #[test]
168	    fn test_valid_script_no_errors() {
169	        let uri = Url::parse("file:///test.rks").unwrap();
170	        let mut doc = make_doc("# Chapter\n角色：\"台词\"");
171	        analyze_document(&uri, &mut doc, "");
172	        assert!(doc.script.is_some(), "有效脚本应成功解析");
173	        assert!(doc.diagnostics.is_empty(), "有效脚本不应产生诊断");
174	    }
175	
176	    #[test]
177	    fn test_parse_error_produces_diagnostic() {
178	        let uri = Url::parse("file:///test.rks").unwrap();
179	        // changeBG 缺少必要的图片路径参数，应产生 MissingParameter 错误
180	        let mut doc = make_doc("changeBG");
181	        analyze_document(&uri, &mut doc, "");
182	        assert!(!doc.diagnostics.is_empty(), "解析错误应转换为诊断");
183	        assert_eq!(
184	            doc.diagnostics[0].severity,
185	            Some(tower_lsp::lsp_types::DiagnosticSeverity::ERROR),
186	            "解析错误应为 ERROR 级别"
187	        );
188	    }
189	
190	    #[test]
191	    fn test_undefined_label_diagnostic() {
192	        let uri = Url::parse("file:///test.rks").unwrap();
193	        // goto 引用了一个不存在的标签，语义分析应产生诊断
194	        let mut doc = make_doc("* start\ngoto nonexistent_label");
195	        analyze_document(&uri, &mut doc, "");
196	        let has_undefined_diag = doc
197	            .diagnostics
198	            .iter()
199	            .any(|d| d.message.contains("nonexistent_label") || d.message.contains("未定义"));
200	        assert!(
201	            has_undefined_diag,
202	            "goto 引用不存在的标签应产生包含标签名或'未定义'的诊断"
203	        );
204	    }
205	
206	    #[test]
207	    fn test_parse_error_clears_script() {
208	        let uri = Url::parse("file:///test.rks").unwrap();
209	        let mut doc = make_doc("goto");
210	        analyze_document(&uri, &mut doc, "");
211	        // 解析失败时 script 字段应为 None
212	        assert!(doc.script.is_none(), "解析失败时 script 应为 None");
213	    }
214	}
215	
216	/// 在脚本的 `source_map` 中查找引用了指定资源路径的节点所在行（0-indexed，供 LSP 使用）。
217	///
218	/// 遍历节点，找到第一个资源路径匹配的节点，返回其 LSP 行号（vn-runtime 行号从 1 开始，
219	/// 转换为 0-indexed）。未找到时返回 `None`。
220	fn find_resource_line(script: &Script, path: &str) -> Option<u32> {
221	    use vn_runtime::script::ast::ScriptNode;
222	
223	    for (index, node) in script.nodes.iter().enumerate() {
224	        let matched = match node {
225	            ScriptNode::ChangeBG { path: p, .. }
226	            | ScriptNode::ChangeScene { path: p, .. }
227	            | ScriptNode::PlayAudio { path: p, .. }
228	            | ScriptNode::ShowCharacter { path: Some(p), .. }
229	            | ScriptNode::Cutscene { path: p } => p == path,
230	            _ => false,
231	        };
232	        if matched {
233	            // get_source_line 返回从 1 开始的行号，LSP 需要 0-indexed
234	            let line_1based = script.get_source_line(index).unwrap_or(1);
235	            return Some(line_1based.saturating_sub(1) as u32);
236	        }
237	    }
238	    None
239	}
