19	/// 根据当前文档状态和光标位置生成补全候选。
20	pub(crate) fn complete(state: &ServerState, params: &CompletionParams) -> Vec<CompletionItem> {
21	    let uri = &params.text_document_position.text_document.uri;
22	    let pos = params.text_document_position.position;
23	
24	    let Some(doc) = state.documents.get(uri) else {
25	        return Vec::new();
26	    };
27	
28	    let line_text = get_line_text(&doc.content, pos.line);
29	    // LSP position.character 是 UTF-16 偏移，此处取字符数上界作为截断点
30	    let col = pos.character as usize;
31	    let prefix = char_prefix(line_text, col).trim_start();
32	
33	    // 空行 → 全部指令
34	    if prefix.is_empty() {
35	        return command_completions();
36	    }
37	
38	    // "with " 后 → 过渡效果（优先于其他规则）
39	    if let Some(_after) = find_after_keyword(prefix, "with") {
40	        return transition_completions();
41	    }
42	
43	    // "at " 后 → 位置
44	    if let Some(_after) = find_after_keyword(prefix, "at") {
45	        return position_completions();
46	    }
47	
48	    // "sceneEffect " 后 → 场景效果
49	    if prefix.to_lowercase().starts_with("sceneeffect ") {
50	        return scene_effect_completions();
51	    }
52	
53	    // "goto " 后 → 当前文件标签
54	    if prefix.to_lowercase().starts_with("goto ") {
55	        return label_completions(doc);
56	    }
57	
58	    // 引号内路径上下文 → 资源文件补全
59	    if let Some((asset_type, _path_prefix)) = detect_path_context(prefix) {
60	        return path_completions(&state.assets, &asset_type);
61	    }
62	
63	    // `$` 变量补全
64	    if prefix.contains('$') {
65	        return variable_completions(doc);
66	    }
67	
68	    // 部分指令名输入（无空格且无引号）→ 过滤匹配的指令
69	    if !prefix.contains(' ') && !prefix.contains('"') {
70	        return filtered_command_completions(prefix);
71	    }
72	
73	    Vec::new()
74	}
