175	/// 递归遍历节点列表，收集所有 `SetVar` 节点的变量名。
176	fn collect_variables(nodes: &[vn_runtime::script::ast::ScriptNode], vars: &mut Vec<String>) {
177	    use vn_runtime::script::ast::ScriptNode;
178	    for node in nodes {
179	        match node {
180	            ScriptNode::SetVar { name, .. } => vars.push(name.clone()),
181	            ScriptNode::Conditional { branches } => {
182	                for branch in branches {
183	                    collect_variables(&branch.body, vars);
184	                }
185	            }
186	            _ => {}
187	        }
