191	/// 获取文档第 `line`（0-indexed）行的文本切片。
192	///
193	/// 若行号超出范围，返回空字符串。
194	fn get_line_text(content: &str, line: u32) -> &str {
195	    content.lines().nth(line as usize).unwrap_or("")
196	}
197	
198	/// 返回 `text` 的前 `char_count` 个字符组成的切片。
199	///
200	/// 将 UTF-16 偏移（`pos.character`）近似为字符数，取实际字符边界以避免字节切片 panic。
201	/// 若 `char_count` 超出字符串长度则返回整个字符串。
202	fn char_prefix(text: &str, char_count: usize) -> &str {
203	    match text.char_indices().nth(char_count) {
204	        #[expect(
205	            clippy::string_slice,
206	            reason = "byte_idx 来自 char_indices()，保证是字符边界，切片安全"
207	        )]
208	        Some((byte_idx, _)) => &text[..byte_idx],
209	        None => text,
210	    }
211	}
212	
213	/// 在 `text` 中查找关键字（如 `"with"`、`"at"`）后面的内容。
214	///
215	/// 匹配规则：关键字后跟一个空格，且匹配时大小写不敏感。
216	/// 返回关键字加空格之后的子串；若未找到则返回 `None`。
217	fn find_after_keyword<'a>(text: &'a str, keyword: &str) -> Option<&'a str> {
218	    let lower = text.to_lowercase();
219	    let needle = format!("{keyword} ");
220	    // 查找最后一次出现，支持 "show ... with ..." 这类多关键字行
221	    let pos = lower.rfind(&needle)?;
222	    // needle 仅含 ASCII，字节长度等于字符长度，此处按字符边界截取原始切片
223	    let byte_start = pos + needle.len();
224	    text.get(byte_start..)
225	}
