227	/// 检测光标是否处于资源路径引号上下文中。
228	///
229	/// 匹配模式：`<指令> "<路径前缀>`（引号未闭合）。
230	/// 返回 `(资源类型, 已输入的路径前缀)`；未匹配则返回 `None`。
231	fn detect_path_context(prefix: &str) -> Option<(AssetType, &str)> {
232	    let lower = prefix.to_lowercase();
233	
234	    // 指令小写前缀 → 资源类型映射
235	    let mappings: &[(&str, AssetType)] = &[
236	        ("changebg ", AssetType::Image),
237	        ("changescene ", AssetType::Image),
238	        ("show ", AssetType::Image),
239	        ("bgm ", AssetType::Audio),
240	        ("sfx ", AssetType::Audio),
241	        ("callscript ", AssetType::Script),
242	        ("cutscene ", AssetType::Video),
243	    ];
244	
245	    for (cmd, asset_type) in mappings {
246	        if lower.starts_with(cmd) {
247	            // cmd 由纯 ASCII 字母和一个尾空格组成，cmd.len() 等于字节数，切片安全
248	            #[expect(
249	                clippy::string_slice,
250	                reason = "cmd 为纯 ASCII，cmd.len() 必然是 prefix 的字符边界"
251	            )]
252	            let after_cmd = &prefix[cmd.len()..];
253	            // 必须以 `"` 开头且只有一个 `"`（未闭合）
254	            if after_cmd.starts_with('"') && after_cmd.matches('"').count() == 1 {
255	                // `"` 是 ASCII 单字节，[1..] 是安全的字符边界切片
256	                #[expect(
257	                    clippy::string_slice,
258	                    reason = r#"after_cmd 以 `"` 开头，`"` 是 ASCII 单字节，[1..] 是安全的字符边界"#
259	                )]
260	                let path_prefix = &after_cmd[1..];
261	                return Some((asset_type.clone(), path_prefix));
262	            }
263	        }
264	    }
265	    None
266	}
