//! # 补全逻辑
//!
//! 根据光标所在行的上下文，生成上下文感知的 LSP 补全候选列表：
//! - 行首或部分指令名输入 → 指令名补全
//! - `with ` 后面 → 过渡效果补全
//! - `at ` 后面 → 位置补全
//! - `sceneEffect ` 后面 → 场景效果补全
//! - `goto ` 后面 → 当前文件标签补全
//! - 资源路径引号内（`changeBG "`、`show "`、`bgm "` 等）→ 资源文件补全

use tower_lsp::lsp_types::{CompletionItem, CompletionItemKind, CompletionParams, Documentation};

use crate::{
    assets::{AssetIndex, AssetType},
    builtins::{COMMANDS, POSITIONS, SCENE_EFFECTS, TRANSITIONS},
    state::{DocumentState, ServerState},
};

/// 根据当前文档状态和光标位置生成补全候选。
pub(crate) fn complete(state: &ServerState, params: &CompletionParams) -> Vec<CompletionItem> {
    let uri = &params.text_document_position.text_document.uri;
    let pos = params.text_document_position.position;

    let Some(doc) = state.documents.get(uri) else {
        return Vec::new();
    };

    let line_text = get_line_text(&doc.content, pos.line);
    // LSP position.character 是 UTF-16 偏移，此处取字符数上界作为截断点
    let col = pos.character as usize;
    let prefix = char_prefix(line_text, col).trim_start();

    // 空行 → 全部指令
    if prefix.is_empty() {
        return command_completions();
    }

    // "with " 后 → 过渡效果（优先于其他规则）
    if let Some(_after) = find_after_keyword(prefix, "with") {
        return transition_completions();
    }

    // "at " 后 → 位置
    if let Some(_after) = find_after_keyword(prefix, "at") {
        return position_completions();
    }

    // "sceneEffect " 后 → 场景效果
    if prefix.to_lowercase().starts_with("sceneeffect ") {
        return scene_effect_completions();
    }

    // "goto " 后 → 当前文件标签
    if prefix.to_lowercase().starts_with("goto ") {
        return label_completions(doc);
    }

    // 引号内路径上下文 → 资源文件补全
    if let Some((asset_type, _path_prefix)) = detect_path_context(prefix) {
        return path_completions(&state.assets, &asset_type);
    }

    // `$` 变量补全
    if prefix.contains('$') {
        return variable_completions(doc);
    }

    // 部分指令名输入（无空格且无引号）→ 过滤匹配的指令
    if !prefix.contains(' ') && !prefix.contains('"') {
        return filtered_command_completions(prefix);
    }

    Vec::new()
}

/// 返回所有指令的补全候选列表。
fn command_completions() -> Vec<CompletionItem> {
    COMMANDS
        .iter()
        .map(|cmd| CompletionItem {
            label: cmd.name.to_string(),
            kind: Some(CompletionItemKind::KEYWORD),
            detail: Some(cmd.syntax.to_string()),
            documentation: Some(Documentation::String(cmd.description.to_string())),
            ..Default::default()
        })
        .collect()
}

/// 返回与前缀匹配的指令补全候选列表（大小写不敏感）。
fn filtered_command_completions(prefix: &str) -> Vec<CompletionItem> {
    let lower = prefix.to_lowercase();
    COMMANDS
        .iter()
        .filter(|cmd| cmd.name.to_lowercase().starts_with(&lower))
        .map(|cmd| CompletionItem {
            label: cmd.name.to_string(),
            kind: Some(CompletionItemKind::KEYWORD),
            detail: Some(cmd.syntax.to_string()),
            documentation: Some(Documentation::String(cmd.description.to_string())),
            ..Default::default()
        })
        .collect()
}

/// 返回所有过渡效果的补全候选列表。
fn transition_completions() -> Vec<CompletionItem> {
    TRANSITIONS
        .iter()
        .map(|&t| CompletionItem {
            label: t.to_string(),
            kind: Some(CompletionItemKind::ENUM_MEMBER),
            ..Default::default()
        })
        .collect()
}

/// 返回所有立绘位置的补全候选列表。
fn position_completions() -> Vec<CompletionItem> {
    POSITIONS
        .iter()
        .map(|&p| CompletionItem {
            label: p.to_string(),
            kind: Some(CompletionItemKind::ENUM_MEMBER),
            ..Default::default()
        })
        .collect()
}

/// 返回所有场景效果的补全候选列表。
fn scene_effect_completions() -> Vec<CompletionItem> {
    SCENE_EFFECTS
        .iter()
        .map(|&e| CompletionItem {
            label: e.to_string(),
            kind: Some(CompletionItemKind::FUNCTION),
            ..Default::default()
        })
        .collect()
}

/// 从文档 AST 中提取标签名，返回标签补全候选列表。
fn label_completions(doc: &DocumentState) -> Vec<CompletionItem> {
    let Some(script) = &doc.script else {
        return Vec::new();
    };
    vn_runtime::diagnostic::get_defined_labels(script)
        .into_iter()
        .map(|label| CompletionItem {
            label: label.to_string(),
            kind: Some(CompletionItemKind::REFERENCE),
            ..Default::default()
        })
        .collect()
}

/// 从文档 AST 中提取所有已声明变量名，返回变量补全候选列表。
fn variable_completions(doc: &DocumentState) -> Vec<CompletionItem> {
    let Some(script) = &doc.script else {
        return Vec::new();
    };
    let mut vars: Vec<String> = Vec::new();
    collect_variables(&script.nodes, &mut vars);
    vars.sort();
    vars.dedup();
    vars.into_iter()
        .map(|name| CompletionItem {
            label: format!("${name}"),
            kind: Some(CompletionItemKind::VARIABLE),
            ..Default::default()
        })
        .collect()
}

/// 递归遍历节点列表，收集所有 `SetVar` 节点的变量名。
fn collect_variables(nodes: &[vn_runtime::script::ast::ScriptNode], vars: &mut Vec<String>) {
    use vn_runtime::script::ast::ScriptNode;
    for node in nodes {
        match node {
            ScriptNode::SetVar { name, .. } => vars.push(name.clone()),
            ScriptNode::Conditional { branches } => {
                for branch in branches {
                    collect_variables(&branch.body, vars);
                }
            }
            _ => {}
        }
    }
}

/// 获取文档第 `line`（0-indexed）行的文本切片。
///
/// 若行号超出范围，返回空字符串。
fn get_line_text(content: &str, line: u32) -> &str {
    content.lines().nth(line as usize).unwrap_or("")
}

/// 返回 `text` 的前 `char_count` 个字符组成的切片。
///
/// 将 UTF-16 偏移（`pos.character`）近似为字符数，取实际字符边界以避免字节切片 panic。
/// 若 `char_count` 超出字符串长度则返回整个字符串。
fn char_prefix(text: &str, char_count: usize) -> &str {
    match text.char_indices().nth(char_count) {
        #[expect(
            clippy::string_slice,
            reason = "byte_idx 来自 char_indices()，保证是字符边界，切片安全"
        )]
        Some((byte_idx, _)) => &text[..byte_idx],
        None => text,
    }
}

/// 在 `text` 中查找关键字（如 `"with"`、`"at"`）后面的内容。
///
/// 匹配规则：关键字后跟一个空格，且匹配时大小写不敏感。
/// 返回关键字加空格之后的子串；若未找到则返回 `None`。
fn find_after_keyword<'a>(text: &'a str, keyword: &str) -> Option<&'a str> {
    let lower = text.to_lowercase();
    let needle = format!("{keyword} ");
    // 查找最后一次出现，支持 "show ... with ..." 这类多关键字行
    let pos = lower.rfind(&needle)?;
    // needle 仅含 ASCII，字节长度等于字符长度，此处按字符边界截取原始切片
    let byte_start = pos + needle.len();
    text.get(byte_start..)
}

/// 检测光标是否处于资源路径引号上下文中。
///
/// 匹配模式：`<指令> "<路径前缀>`（引号未闭合）。
/// 返回 `(资源类型, 已输入的路径前缀)`；未匹配则返回 `None`。
fn detect_path_context(prefix: &str) -> Option<(AssetType, &str)> {
    let lower = prefix.to_lowercase();

    // 指令小写前缀 → 资源类型映射
    let mappings: &[(&str, AssetType)] = &[
        ("changebg ", AssetType::Image),
        ("changescene ", AssetType::Image),
        ("show ", AssetType::Image),
        ("bgm ", AssetType::Audio),
        ("sfx ", AssetType::Audio),
        ("callscript ", AssetType::Script),
        ("cutscene ", AssetType::Video),
    ];

    for (cmd, asset_type) in mappings {
        if lower.starts_with(cmd) {
            // cmd 由纯 ASCII 字母和一个尾空格组成，cmd.len() 等于字节数，切片安全
            #[expect(
                clippy::string_slice,
                reason = "cmd 为纯 ASCII，cmd.len() 必然是 prefix 的字符边界"
            )]
            let after_cmd = &prefix[cmd.len()..];
            // 必须以 `"` 开头且只有一个 `"`（未闭合）
            if after_cmd.starts_with('"') && after_cmd.matches('"').count() == 1 {
                // `"` 是 ASCII 单字节，[1..] 是安全的字符边界切片
                #[expect(
                    clippy::string_slice,
                    reason = r#"after_cmd 以 `"` 开头，`"` 是 ASCII 单字节，[1..] 是安全的字符边界"#
                )]
                let path_prefix = &after_cmd[1..];
                return Some((asset_type.clone(), path_prefix));
            }
        }
    }
    None
}

/// 返回指定资源类型的文件补全候选列表。
fn path_completions(assets: &AssetIndex, asset_type: &AssetType) -> Vec<CompletionItem> {
    assets
        .completions_for_type(asset_type)
        .into_iter()
        .map(|entry| CompletionItem {
            label: entry.relative_path.clone(),
            kind: Some(CompletionItemKind::FILE),
            ..Default::default()
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use tower_lsp::lsp_types::{
        CompletionParams, PartialResultParams, Position, TextDocumentIdentifier,
        TextDocumentPositionParams, Url, WorkDoneProgressParams,
    };

    use super::*;
    use crate::state::{DocumentState, ServerState};

    fn make_params(uri: Url, line: u32, character: u32) -> CompletionParams {
        CompletionParams {
            text_document_position: TextDocumentPositionParams {
                text_document: TextDocumentIdentifier { uri },
                position: Position { line, character },
            },
            work_done_progress_params: WorkDoneProgressParams::default(),
            partial_result_params: PartialResultParams::default(),
            context: None,
        }
    }

    fn make_state_with_content(content: &str) -> (ServerState, Url) {
        let uri = Url::parse("file:///test.rks").unwrap();
        let mut state = ServerState::new();
        let mut doc = DocumentState {
            content: content.to_string(),
            version: 1,
            script: None,
            diagnostics: Vec::new(),
        };
        // 解析脚本以填充 script 字段（标签补全依赖 AST）
        let mut parser = vn_runtime::script::parser::Parser::new();
        if let Ok(script) = parser.parse("test", content) {
            doc.script = Some(script);
        }
        state.documents.insert(uri.clone(), doc);
        (state, uri)
    }

    #[test]
    fn test_empty_line_returns_all_commands() {
        let (state, uri) = make_state_with_content("");
        let params = make_params(uri, 0, 0);
        let items = complete(&state, &params);
        assert!(!items.is_empty(), "空行应返回所有指令补全");
        assert!(
            items.iter().any(|i| i.label == "changeBG"),
            "应包含 changeBG 指令"
        );
        assert!(items.iter().any(|i| i.label == "goto"), "应包含 goto 指令");
    }

    #[test]
    fn test_partial_command_filters_completions() {
        let (state, uri) = make_state_with_content("change");
        let params = make_params(uri, 0, 6);
        let items = complete(&state, &params);
        // 所有返回项都应以 "change" 开头（大小写不敏感）
        assert!(!items.is_empty(), "部分指令名应有补全候选");
        for item in &items {
            assert!(
                item.label.to_lowercase().starts_with("change"),
                "候选 '{}' 不匹配前缀 'change'",
                item.label
            );
        }
    }

    #[test]
    fn test_goto_label_completion() {
        // 内容中定义了两个标签，goto 后（补全时光标在行尾）应给出标签补全
        // 注意：goto 必须有合法标签才能通过解析器，所以在已解析的 script 中手动预填标签
        let content = "* start\n* ending\ngoto start";
        let (mut state, uri) = make_state_with_content(content);

        // 模拟用户正在编辑 goto 行，将文档内容改为 "goto "（不完整，触发补全）
        // 但保留已解析的 script（含标签）以测试标签补全逻辑
        if let Some(doc) = state.documents.get_mut(&uri) {
            doc.content = "* start\n* ending\ngoto ".to_string();
        }

        let params = make_params(uri, 2, 5);
        let items = complete(&state, &params);
        assert!(
            items.iter().any(|i| i.label == "start"),
            "应包含标签 start，实际候选: {:?}",
            items.iter().map(|i| &i.label).collect::<Vec<_>>()
        );
        assert!(
            items.iter().any(|i| i.label == "ending"),
            "应包含标签 ending"
        );
    }

    #[test]
    fn test_with_keyword_triggers_transition_completions() {
        // "changeBG \"bg.png\" with " 共 24 个字符（含尾部空格），character=24 意味光标在行尾
        let line = "changeBG \"bg.png\" with ";
        let char_count = line.chars().count() as u32;
        let (state, uri) = make_state_with_content(line);
        let params = make_params(uri, 0, char_count);
        let items = complete(&state, &params);
        assert!(!items.is_empty(), "with 后应有过渡效果补全");
        // 所有候选应为 ENUM_MEMBER 类型
        assert!(
            items
                .iter()
                .all(|i| i.kind == Some(CompletionItemKind::ENUM_MEMBER)),
            "过渡效果补全应为 ENUM_MEMBER 类型"
        );
    }
}

