//! # 资源索引
//!
//! 启动时扫描 workspace 的 `assets/` 目录，建立资源文件索引，
//! 按文件类型分类，供补全和资源存在性验证使用。

use std::{collections::BTreeMap, path::Path};

use walkdir::WalkDir;

/// 资源文件类型
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum AssetType {
    /// 图片（背景/立绘/场景）
    Image,
    /// 音频（BGM/SFX）
    Audio,
    /// 视频（cutscene）
    Video,
    /// 脚本文件（.rks）
    Script,
    /// 其他类型
    Other,
}

/// 单条资源记录
#[derive(Debug, Clone)]
pub(crate) struct AssetEntry {
    /// 相对于 `assets/` 目录的路径，使用 `/` 分隔符
    pub(crate) relative_path: String,
    /// 资源类型
    pub(crate) asset_type: AssetType,
}

/// 资源文件索引
///
/// 以 `BTreeMap` 保证遍历顺序稳定（补全列表按字典序排列）。
#[derive(Debug, Default)]
pub(crate) struct AssetIndex {
    entries: BTreeMap<String, AssetEntry>,
}

impl AssetIndex {
    /// 扫描 `assets_dir` 目录，构建资源索引。
    ///
    /// 若目录不存在则返回空索引，不报错。
    pub(crate) fn scan(assets_dir: &Path) -> Self {
        let mut index = Self::default();
        if !assets_dir.exists() {
            return index;
        }
        for entry in WalkDir::new(assets_dir).into_iter().filter_map(Result::ok) {
            if !entry.file_type().is_file() {
                continue;
            }
            let rel_path = entry
                .path()
                .strip_prefix(assets_dir)
                .unwrap_or(entry.path())
                .to_string_lossy()
                .replace('\\', "/");
            let asset_type = classify_extension(entry.path());
            index.entries.insert(
                rel_path.clone(),
                AssetEntry {
                    relative_path: rel_path,
                    asset_type,
                },
            );
        }
        index
    }

    /// 返回指定类型的所有资源条目（用于补全过滤）。
    pub(crate) fn completions_for_type(&self, filter_type: &AssetType) -> Vec<&AssetEntry> {
        self.entries
            .values()
            .filter(|e| &e.asset_type == filter_type)
            .collect()
    }

    /// 返回全部资源条目的迭代器。
    #[expect(dead_code, reason = "后续功能（如悬停提示、资源浏览）将使用此接口")]
    pub(crate) fn all_entries(&self) -> impl Iterator<Item = &AssetEntry> {
        self.entries.values()
    }

    /// 检查给定路径（相对于 `assets/`）是否存在于索引中。
    ///
    /// 路径分隔符会规范化为 `/` 后再查找。
    pub(crate) fn exists(&self, relative_path: &str) -> bool {
        let normalized = relative_path.replace('\\', "/");
        self.entries.contains_key(&normalized)
    }
}

/// 根据文件扩展名判断资源类型（大小写不敏感）。
fn classify_extension(path: &Path) -> AssetType {
    match path
        .extension()
        .and_then(|e| e.to_str())
        .unwrap_or("")
        .to_lowercase()
        .as_str()
    {
        "png" | "jpg" | "jpeg" | "webp" | "bmp" => AssetType::Image,
        "mp3" | "ogg" | "wav" | "flac" => AssetType::Audio,
        "mp4" | "webm" => AssetType::Video,
        "rks" => AssetType::Script,
        _ => AssetType::Other,
    }
}

