function Normalize-AssetPath($basePath, $relativePath) {
    $combined = "$basePath/$relativePath"
    $parts = [System.Collections.Generic.List[string]]::new()
    foreach ($seg in $combined.Split('/')) {
        if ($seg -eq '..') {
            if ($parts.Count -gt 0) { $parts.RemoveAt($parts.Count - 1) }
        } elseif ($seg -ne '.' -and $seg -ne '') {
            $parts.Add($seg)
        }
    }
    return ($parts -join '/')
}

foreach ($file in $scriptFiles) {
    $rel = $file.DirectoryName.Substring($assetsRoot.Length + 1).Replace('\', '/')
    $content = [System.IO.File]::ReadAllText($file.FullName, [System.Text.Encoding]::UTF8)
    $fileReplacements = 0

    $newContent = [regex]::Replace($content, '"([^"]*\.\./[^"]*)"', {
        param($match)
        $oldPath = $match.Groups[1].Value
        $newPath = Normalize-AssetPath $rel $oldPath
        $script:fileReplacements++
        $script:totalReplacements++
        return "`"$newPath`""
    })

    if ($fileReplacements -gt 0) {
        [System.IO.File]::WriteAllText($file.FullName, $newContent, (New-Object System.Text.UTF8Encoding $false))
        Write-Output "$($file.Name): $fileReplacements replacements (base: $rel)"
    }
}

